export const meta = {
  name: 'build-F2',
  description: 'Plan, build, adversarially review and fix item F2 (Summon on the fly) of docs/27-v1.4.md',
  phases: [{ title: 'Plan' }, { title: 'Build' }, { title: 'Review' }, { title: 'Fix' }],
}
const W = 'docs/progress/v1.4/work/F2'
const CTX = `Item: F2 "Summon on the fly" in docs/27-v1.4.md (the "### F2 Summon on the fly" section). Tranche v1.4, work folder ${W}/ (look at docs/progress/v1.4/work/F1/ for the file shapes). Unattended run: nobody can answer questions. Take decisions from docs/27-v1.4.md's Decisions where they cover it; otherwise use judgment and record the decision in the item's record (${W}/ files, and the 27 item note). Fixture data only (INV-18), never a real PAT, the app never writes to ADO. Do NOT commit or push.`
const VERDICT = { type: 'object', properties: {
  verdict: { type: 'string', enum: ['accept', 'fix', 'replan'] },
  blockersAndMajors: { type: 'array', items: { type: 'string' } },
  minors: { type: 'array', items: { type: 'string' } },
}, required: ['verdict', 'blockersAndMajors', 'minors'] }

phase('Plan')
const plan = await agent(`${CTX}\nWrite ${W}/packet.md and ${W}/plan-1.json for F2 (it depends on F1, already accepted). Decide the approach; name every schedule-golden change the builder must make. Return a short summary of the approach.`, { agentType: 'planner', phase: 'Plan', label: 'planner' })

phase('Build')
const build = await agent(`${CTX}\nBuild F2 from ${W}/packet.md. Planner summary: ${plan}\nMeet every acceptance bullet (gallery jump-in cell full + reduced motion, the unit test, 15 §7 row + docTables.test.ts, updated schedule goldens named in the packet, ledger saving per pod via scripts/pacing-ledger). Update 13 §6, 05 §8 per the item's Touches. Run npm run typecheck, npm run lint, npm test, and the e2e specs mapped in tests/README.md for what changed plus npm run e2e:keystone; fix failures. Write ${W}/build-1.json. Return a summary including check results.`, { agentType: 'builder', phase: 'Build', label: 'builder' })

phase('Review')
const review = await agent(`${CTX}\nFresh adversarial review of F2's uncommitted diff (git diff HEAD, plus untracked files) against ${W}/packet.md acceptance, docs/27-v1.4.md's F2 Decided text, and the project rules (02 §1 invariants, R1–R14, 15-reference tables). Verify claims yourself: run the unit tests and the gallery/mapped e2e specs rather than trusting the build record. Write ${W}/review-1.md and review-1.json. Builder summary: ${build}`, { agentType: 'reviewer', phase: 'Review', label: 'reviewer', schema: VERDICT })

let fix = null, review2 = null
if (review && review.verdict !== 'accept' || (review && review.minors.length)) {
  phase('Fix')
  fix = await agent(`${CTX}\nFix the Blocker and Major findings (and cheap Minors) in ${W}/review-1.md. Findings: ${JSON.stringify(review)}. Rerun typecheck, lint, npm test and the mapped e2e specs + e2e:keystone. Write ${W}/fix-1.json. Return a summary with check results.`, { agentType: 'fixer', phase: 'Fix', label: 'fixer' })
  if (review.blockersAndMajors.length) {
    review2 = await agent(`${CTX}\nFresh adversarial re-review of F2's uncommitted diff after the fix in ${W}/fix-1.json; check each finding of ${W}/review-1.md is resolved and nothing regressed. Run the unit tests and mapped e2e specs. Write ${W}/review-2.md and review-2.json.`, { agentType: 'reviewer', phase: 'Fix', label: 'reviewer-2', schema: VERDICT })
  }
}
return { plan, build, review, fix, review2 }

