def sub(p,a,b):
    t=open(p).read(); assert a in t,(p,a); t=t.replace(a,b,1); open(p,'w').write(t)
T='tests/unit/pacingBuilt.test.ts'
sub(T,"!x.id.startsWith('E10'))).toEqual(before);","!x.id.startsWith('E10') && !x.id.startsWith('F2'))).toEqual(before);")
sub(T,"  it('E1 to E5 measure what","""  it('F2, summon on the fly: rows on all seven pods; undirected, each pod saves at least a summon\\'s 900 ms and never costs time; directed, never costs time', () => {
    const r = rows.filter((x) => x.id === 'F2');
    expect(r).toHaveLength(7);
    for (const x of r) expect(x.savedMs, x.pod).toBeGreaterThanOrEqual(900);
    // Comet has one summon: tell 300 and land 600 go (the plate's ride then fits inside the old hold).
    expect(r.find((x) => x.pod.includes('Comet'))!.savedMs).toBe(900);
    const d = rows.filter((x) => x.id === 'F2+');
    expect(d).toHaveLength(7);
    for (const x of d) expect(x.savedMs, x.pod).toBeGreaterThanOrEqual(0);
  }, 180_000);

  it('E1 to E5 measure what""")
C='tests/unit/commands.test.ts'
s=open(C).read()
i=s.index("  it('Station jump-in issues no beacon")
j=s.index("    const act = tender.act!")
new="""  it('Station jump-in (27 F2): the summoner passes through the spot with no hold, and the call blip and the arrival start together', () => {
    const view = (key: string, x: number) => ({ key, node: { world: { x, y: 0, r: 20 }, projectionKey: key, kind: 'x' }, at: [x, 0] });
    const cast = { facility: [view('fac', 100)], agent: [view('ag', 0)], seat: [view('s1', 200), view('s2', 300)] };
    const jump = maneuvers.find((m) => m.title === 'Station jump-in')!.phase as Record<string, (c: unknown, m: unknown) => Call[]>;
    const tender = maneuvers.find((m) => m.title === 'Shuttle tender')!.phase as Record<string, (c: unknown, m: unknown) => Call[]>;
    const m = { ...planned(RULE.facilityEnter, 'e1', { facility: [WI1], agent: [A] }), passes: true as const };
    // Only the gather and the act: no tell, no land, no beacon, no fold ring.
    expect(Object.keys(jump).sort()).toEqual(['act', 'gather']);
    expect(m.phases.map((p) => p.phase)).toEqual(['gather', 'act']);
    const gather = jump.gather!(cast, m);
    expect(gather.filter((c) => c.cmd === 'spark' || c.cmd === 'ring')).toEqual([]);
    const pursue = gather.find((c) => c.cmd === 'pursue') as unknown as { args: { durS: number; holdS: number; backS: number; pass?: boolean; waitS?: number } };
    expect(pursue).toBeDefined();
    // No hold between its flight and its next place: it flies through the spot (`pass`), never parked there.
    expect(pursue.args.pass).toBe(true);
    expect(pursue.args.holdS).toBe(0);
    expect(pursue.args.waitS).toBeUndefined();
    // It reaches the spot (the blip) as the act starts, and its leg on to its rest is as long as its plate rides.
    const act = jump.act!(cast, m);
    const blipAtMs = pursue.args.durS * 1000;
    const actAtMs = m.phases.find((p) => p.phase === 'act')!.atMs;
    expect(Math.abs(actAtMs - blipAtMs)).toBeLessThanOrEqual(50);
    expect(pursue.args.backS * 1000).toBe(releaseOfPlay(m) - actAtMs);
    // The blip and the station's arrival are issued together (no delay), in the same hue.
    const rings = act.filter((c) => c.cmd === 'ring') as unknown as { args: { color: number }; delayMs?: number }[];
    expect(rings).toHaveLength(2); // the blip, and the station's own
    expect(rings[0]!.args.color).toBe(rings[1]!.args.color);
    expect([...act.filter((c) => c.cmd === 'ring' || 'act' in c), ...act.filter((c) => c.cmd === 'flare')].every((c) => !(c as { delayMs?: number }).delayMs)).toBe(true);
    expect(act.some((c) => 'act' in c)).toBe(true);
"""
s=s[:i]+new+s[j:]
s=s.replace("import { PACE_RULES, RULE } from '@shared/engine/pace';","import { releaseOfPlay } from '@shared/engine/maneuvers';\nimport { PACE_RULES, RULE } from '@shared/engine/pace';",1)
open(C,'w').write(s)
EOF
